// `auth generate` writes the schema without our header. Put it back, then format.
import { readFileSync, writeFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';

const file = 'src/lib/server/db/schema/auth.ts';
const header = `// Copyright 2026 appinventor.org
// Released under the Apache License, Version 2.0
// http://www.apache.org/licenses/LICENSE-2.0

// Generated by \`pnpm auth:generate\` from better-auth's config. Do not edit by
// hand: change src/lib/server/auth/create-auth.ts and regenerate.

`;
const source = readFileSync(file, 'utf8').replace(/^\/\/ Copyright[\s\S]*?regenerate\.\n\n/, '');
writeFileSync(file, header + source);
execFileSync('pnpm', ['exec', 'prettier', '--write', file], { stdio: 'inherit' });
